 "content": "def transform(grid):
    """Project each top-row color downward; matching side markers turn the ray."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0

    for col, color in enumerate(grid[0]):
        if color == 0:
            continue
        markers = [(r, c) for r in range(1, h) for c in range(w)
                   if grid[r][c] == color]
        # Side markers indicate where the vertical ray turns horizontally.
        side_markers = [(r, c) for r, c in markers if c == 0 or c == w - 1]
        if side_markers:
            r, c = side_markers[0]
            for rr in range(1, r + 1):
                out[rr][col] = color
            if c == 0:
                for cc in range(0, col + 1):
                    out[r][cc] = color
            else:
                for cc in range(col, w):
                    out[r][cc] = color
        else:
            for rr in range(1, h):
                out[rr][col] = color
    return out
